// ===== INPUT SANITIZER — Anti Prompt Injection =====
const item = $input.first().json;
const body = item.body || item;
const rawMaterial = body.material || body.rawText || body.text || "";

const technicalPatterns = [
    /webhookId/i, /x-real-ip/i, /user-agent/i, /"headers"\s*:/i,
    /authorization:\s*bearer/i, /api[_-]?key\s*[:=]/i, /access[_-]?token\s*[:=]/i,
    /"typeVersion"/i, /"nodeGroups"/i, /-----BEGIN .* KEY-----/i
];

for (const pattern of technicalPatterns) {
    if (pattern.test(rawMaterial)) {
        throw new Error("REJECTED: Materi terdeteksi sebagai data teknis/sistem, bukan konten scroll.");
    }
}

function cleanStr(str, maxLen) {
    if (!str || typeof str !== "string") return "";
    return str
        .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "")
        .replace(/ignore\s+(all\s+)?(previous|above|prior)\s+instructions?/gi, "[DIHAPUS]")
        .replace(/you\s+are\s+now\s+(a\s+)?/gi, "[DIHAPUS] ")
        .replace(/forget\s+(everything|all)\s+(you|above)/gi, "[DIHAPUS]")
        .replace(/system\s*:\s*/gi, "[DIHAPUS]: ")
        .replace(/\[INST\]|\[\/INST\]|<\|system\|>|<\|user\|>|<\|assistant\|>/gi, "[DIHAPUS]")
        .replace(/\{\{/g, "{ {")
        .replace(/\}\}/g, "} }")
        .slice(0, maxLen)
        .trim();
}

let sanitized = cleanStr(rawMaterial, 15000);
if (sanitized.length < 15) {
    throw new Error("REJECTED: Materi terlalu pendek untuk diproses.");
}

return [{
    json: {
        ...item,
        _sanitized: {
            material: sanitized,
            brandName: cleanStr(body.brandName || "", 80),
            persona: cleanStr(body.persona || "Profesional", 200),
            targetAudience: cleanStr(body.targetAudience || "Umum", 200),
            scrollStyle: body.scrollStyle === "snap" ? "snap" : "free-flow",
            deckTheme: cleanStr(body.deckTheme || "", 80),
            revealStyle: ["slide-up", "tilt-3d", "fade", "mask-wipe"].includes(body.revealStyle) ? body.revealStyle : "slide-up",
            parallax: ["off", "subtle", "strong"].includes(body.parallax) ? body.parallax : "subtle",
            sectionCount: Math.max(3, Math.min(12, parseInt(body.sectionCount || 6, 10) || 6)),
            language: (['id','en','ar'].includes(body.language || body.outputLanguage) ? (body.language || body.outputLanguage) : 'id')
        }
    }
}];

// ===== ROBUST JSON CLEANER & PARSER =====
const item = $input.first().json;
let raw = item.text || item.output || item.content || item.response || item.data || item.result || item.message?.content || "";
if (typeof raw === 'object') raw = JSON.stringify(raw);
raw = String(raw || '').trim();

if (!raw) {
  for (const k of Object.keys(item)) {
    if (typeof item[k] === 'string' && item[k].trim().length > 10) { raw = item[k]; break; }
  }
}

// 1. Strip markdown code fences
const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
if (fenceMatch) {
  raw = fenceMatch[1].trim();
} else {
  raw = raw.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "").trim();
}

// 2. Normalisasi smart quotes & whitespace kontrol
raw = raw
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/[\u2018\u2019]/g, "'")
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, "");

// 3. Bersihkan trailing commas
raw = raw.replace(/,\s*([\}\]])/g, '$1');

function tryParse(str) {
  try { return JSON.parse(str); } catch (e) { return null; }
}

let parsed = tryParse(raw);

if (!parsed) {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) {
    const candidate = raw.slice(start, end + 1).replace(/,\s*([\}\]])/g, '$1');
    parsed = tryParse(candidate);
  }
}

if (!parsed || !parsed.sections || !Array.isArray(parsed.sections)) {
  throw new Error("Gagal mengurai outline scrollytelling menjadi JSON valid: " + raw.slice(0, 300));
}

return [{ json: parsed }];

