// Validasi persetujuan dan terapkan edit teks per section.
const submission = $input.first().json || {};
const approvalText = 'Saya menyetujui outline ini dan ingin melanjutkan pembuatan scrollytelling';
const approval = submission.approval;
const approved = Array.isArray(approval)
  ? approval.includes(approvalText)
  : String(approval || '') === approvalText;

if (!approved) {
  throw new Error('APPROVAL_REQUIRED: Centang persetujuan sebelum melanjutkan.');
}

// Ambil outline asli agar kind, keyPoints, stats, dan properti visual tidak hilang.
const source = $('Parse JSON').first().json;
const outline = JSON.parse(JSON.stringify(source));

if (!outline || !Array.isArray(outline.sections) || outline.sections.length < 1) {
  throw new Error('OUTLINE_INVALID: Outline sumber tidak memiliki sections yang valid.');
}

function cleanText(value, maxLength) {
  return String(value ?? '')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
    .slice(0, maxLength)
    .trim();
}

outline.sections = outline.sections.map((section, index) => {
  const badge = cleanText(submission[`section_${index}_badge`], 80);
  const title = cleanText(submission[`section_${index}_title`], 240);
  const subtitle = cleanText(submission[`section_${index}_subtitle`], 600);
  const narrative = cleanText(submission[`section_${index}_narrative`], 6000);

  if (!title) {
    throw new Error(`OUTLINE_INVALID: Judul Section ${index + 1} tidak boleh kosong.`);
  }
  if (!narrative) {
    throw new Error(`OUTLINE_INVALID: Narasi Section ${index + 1} tidak boleh kosong.`);
  }

  return {
    ...section,
    badge,
    title,
    subtitle,
    narrative
  };
});

if (outline.sections[0]?.kind !== 'hero') {
  throw new Error('OUTLINE_INVALID: Section pertama wajib memiliki kind hero.');
}
if (outline.sections.at(-1)?.kind !== 'closing') {
  throw new Error('OUTLINE_INVALID: Section terakhir wajib memiliki kind closing.');
}

const settings = $('Input Sanitizer').first().json._sanitized;
return [{
  json: {
    outline,
    renderConfig: {
      brandName: settings.brandName,
      persona: settings.persona,
      targetAudience: settings.targetAudience,
      language: settings.language,
      scrollStyle: settings.scrollStyle,
      deckTheme: settings.deckTheme,
      revealStyle: settings.revealStyle,
      parallax: settings.parallax
    },
    approvedAt: new Date().toISOString()
  }
}];

// Adapt payload dari workflow outline ke format generator lama.
const root = $input.first().json || {};
const body = root.payload || root;
const outline = body.outline || body.approvedOutline;
const cfg = body.renderConfig || {};

if (!outline || !Array.isArray(outline.sections) || outline.sections.length < 1) {
  throw new Error('SUBWORKFLOW_INPUT: payload.outline.sections wajib berupa array dan tidak boleh kosong.');
}

const rawText = outline.sections
  .map((section) => [section.title, section.subtitle, section.narrative].filter(Boolean).join(' '))
  .join('\n\n');

return [{
  json: {
    rawText,
    material: rawText,
    brandName: cfg.brandName || outline.metadata?.topic || 'Sleyd',
    persona: cfg.persona || 'Profesional',
    targetAudience: cfg.targetAudience || 'Umum',
    outputLanguage: cfg.language || outline.metadata?.language || 'id',
    sectionCount: outline.sections.length,
    scrollStyle: cfg.scrollStyle || 'free-flow',
    deckTheme: cfg.deckTheme || '',
    typography: cfg.typography || 'Inter',
    brandLogo: cfg.brandLogo || null,
    coverMedia: cfg.coverMedia || null,
    revealStyle: cfg.revealStyle || 'slide-up',
    parallax: cfg.parallax || 'subtle',
    sessionId: body.sessionId || '',
    approvedAt: body.approvedAt || '',
    approvedOutline: outline
  }
}];

// [Error catcher — auto-added]
try {
const input = $json;
const imageUrl = input.customImageUrl || input.imageUrl || ((input.photos && Array.isArray(input.photos) && input.photos.length > 0) 
  ? (input.photos[0].src.large2x || input.photos[0].src.large) 
  : null);

const { photos, page, per_page, total_results, next_page, error, ...slideData } = input;

return {
  json: {
    ...slideData,
    imageUrl: imageUrl
  }
};
} catch (__err) {
  return [{ json: {
    ...($json || {}),
    imageUrl: null
  } }];
}

// [Error catcher — auto-added]
try {
// ===== SANITIZE HTML — pembersih + safety net =====
const item = $input.first().json;

let raw =
  item.output ??
  item.text ??
  item.content ??
  item.response ??
  item.data ??
  item.result ??
  item.completion ??
  (item.message && item.message.content) ??
  (item.response && item.response.text) ??
  (item.data && item.data.text) ??
  '';

if (typeof raw === 'object') raw = JSON.stringify(raw);
raw = String(raw || '').trim();

if (!raw) {
  const fallback =
    `<section class="scroll-section section-fallback p-16" style="min-height:60vh;display:flex;align-items:center;justify-content:center;">` +
      `<div class="inner text-center">` +
        `<h2 class="text-2xl font-semibold mb-3 editable-text">Bagian ini sedang dimuat...</h2>` +
      `</div>` +
    `</section>`;
  return [{ json: { data: fallback } }];
}

// 1. Bersihkan sisa-sisa markdown fence
raw = raw.replace(/```html/gi, '').replace(/```/g, '').trim();

// 2. Cari titik awal HTML yang valid (<section, <div)
const startSection = raw.toLowerCase().indexOf('<section');
const startDiv     = raw.toLowerCase().indexOf('<div');

let validStartIndex = 0;
if (startSection !== -1) validStartIndex = startSection;
else if (startDiv !== -1) validStartIndex = startDiv;

let cleanHtml = raw.substring(validStartIndex).trim();

// 2.5 Hapus tombol Call to Action / Mulai Sekarang jika ter-generate
cleanHtml = cleanHtml.replace(/<a\b[^>]*class=["'][^"']*\b(?:closing-cta|cta-btn|hero-cta|cta)\b[^"']*["'][^>]*>[\s\S]*?<\/a>/gi, "");
cleanHtml = cleanHtml.replace(/<button\b[^>]*class=["'][^"']*\b(?:closing-cta|cta-btn|hero-cta|cta)\b[^"']*["'][^>]*>[\s\S]*?<\/button>/gi, "");
cleanHtml = cleanHtml.replace(/<(?:a|button)\b[^>]*>[^<]*Mulai Sekarang[^<]*<\/(?:a|button)>/gi, "");

// Bersihkan tag img ber-src "null" jika LLM sempat menulisnya
cleanHtml = cleanHtml.replace(/<img\b[^>]*src=["'](?:null|undefined|)["'][^>]*>/gi, "");

// 3. AUTO-HEAL penutup tag jika terpotong
if (cleanHtml.toLowerCase().startsWith('<section')) {
  const openSections  = (cleanHtml.match(/<section\b/gi) || []).length;
  const closeSections = (cleanHtml.match(/<\/section>/gi) || []).length;
  for (let i = 0; i < openSections - closeSections; i++) cleanHtml += '\n</section>';
} else if (cleanHtml.toLowerCase().startsWith('<div')) {
  // Jika tidak berawalan <section>, bungkus dengan section agar nav dots & GSAP bekerja normal
  cleanHtml = `<section class="scroll-section">${cleanHtml}\n</section>`;
}

return [{ json: { data: cleanHtml.trim() } }];
} catch (__err) {
  return [{ json: {
    __workflowError: true,
    node: "Sanitize HTML",
    message: (__err && __err.message) ? String(__err.message) : String(__err),
    stack: (__err && __err.stack) ? String(__err.stack).slice(0, 1500) : ''
  } }];
}

// [Error catcher]
try {

// ──────────────────────────────────────────────────────────────────────────
// SCROLL MERGER — assembles all section HTML into a full scrollytelling page.
// ──────────────────────────────────────────────────────────────────────────

const item = $input.first().json;
const htmlChunks = Array.isArray(item.html_chunks) ? item.html_chunks : [];

const errorChunk = htmlChunks.find(c => c && c.__workflowError);
if (errorChunk) {
    throw new Error(`SECTION_ERROR in "${errorChunk.node}": ${errorChunk.message}`);
}

const sectionsHtml = htmlChunks
    .map((c, idx) => {
        let raw = typeof c === 'string' ? c : (c.text || c.output || c.data || "");
        raw = raw.trim();
        if (!raw) return "";
        // LCP Optimization (Bab 6.A arsitektur-workflow-html.md)
        // Section 1 (Hero) eager loading + high priority; Section 2+ lazy
        if (idx === 0) {
            raw = raw.replace(/<img\b(?![^>]*\bloading=)/gi, '<img loading="eager" fetchpriority="high"');
        } else {
            raw = raw.replace(/<img\b(?![^>]*\bloading=)/gi, '<img loading="lazy"');
        }
        return raw;
    })
    .filter(s => s.length > 0)
    .join("\n\n");

const fmtFields   = $('Format Fields').first().json || {};
const splitFirst  = $('Split Sections').first().json || {};

const scrollStyle    = fmtFields.scrollStyle || "free-flow";
const revealStyle    = fmtFields.revealStyle || "slide-up";
const parallax       = fmtFields.parallax    || "subtle";
const brandName      = fmtFields.brandName   || "Sleyd";
const outputLanguage = fmtFields.outputLanguage || "id";
const sessionId      = fmtFields.sessionId   || "";

