const fontGoogleUrl  = splitFirst.fontGoogleUrl || `https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;700;800&family=Inter:wght@400;500;600;700&display=swap`;

const slug = sessionId || "deck";

