  color: var(--accent-bright, #38BDF8) !important;
  text-shadow: 0 0 25px rgba(var(--accent-rgb), 0.7), 0 2px 10px rgba(0, 0, 0, 0.8);
}

.section-hero { justify-content: center; min-height: 100vh; min-height: 100dvh; padding: clamp(3rem, 6vh, 5rem) clamp(1.5rem, 5vw, 4rem); }
.hero-bg { position: absolute; inset: 0; z-index: 0; }
.hero-bg img { width: 100%; height: 100%; object-fit: cover; filter: brightness(0.55) contrast(1.1); /* Darkened for 100% text readability */ }
.hero-scrim { 
  position: absolute; inset: 0; z-index: 1; 
  background: linear-gradient(180deg, rgba(6,12,24,0.45) 0%, rgba(6,12,24,0.7) 55%, var(--bg) 100%); 
}
.hero-content { max-width: 920px; }
.hero-title { font-size: clamp(42px, 6.8vw, 86px); font-weight: 800; letter-spacing: -0.04em; line-height: 1.08; max-width: 18ch; text-wrap: balance; margin-bottom: 24px; color: var(--text); }
.hero-sub { font-size: clamp(18px, 2.1vw, 24px); color: var(--text-soft); max-width: 54ch; line-height: 1.65; font-weight: 450; }
.hero-scroll-cue { position: absolute; bottom: 32px; left: 50%; transform: translateX(-50%); z-index: 3; font-size: 11px; letter-spacing: 0.22em; text-transform: uppercase; color: var(--text-soft); display: flex; flex-direction: column; align-items: center; gap: 8px; font-weight: 700; }
.hero-scroll-cue .line { width: 2px; height: 30px; background: var(--accent); animation: cueDraw 2.2s ease-in-out infinite; box-shadow: 0 0 10px var(--accent); }
@keyframes cueDraw { 0% { transform: scaleY(0); transform-origin: top; } 50% { transform: scaleY(1); transform-origin: top; } 51% { transform-origin: bottom; } 100% { transform: scaleY(0); transform-origin: bottom; } }

/* ── 2. Sticky Media Section (FIXED: ample min-height + true sticky media) ── */
.section-sticky-media { padding: 0 !important; display: block !important; min-height: 160vh; overflow: visible !important; }
.section-sticky-media .inner { max-width: 100% !important; margin: 0 !important; }
.sm-grid { display: grid; grid-template-columns: 1.1fr 1fr; width: 100%; min-height: 160vh; position: relative; }
.sm-media { position: sticky; top: 0; height: 100vh; height: 100dvh; overflow: hidden; background: rgba(var(--accent-rgb), 0.08); display: flex; align-items: center; justify-content: center; }
.sm-media img { width: 100%; height: 100%; object-fit: cover; }
.sm-media::after { content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, transparent 65%, var(--bg) 100%); }
html[dir="rtl"] .sm-media::after { background: linear-gradient(270deg, transparent 65%, var(--bg) 100%); }
.sm-text { padding: 14vh 5vw 16vh 5vw; display: flex; flex-direction: column; justify-content: center; gap: 32px; }
.sm-card { 
  background: var(--surface); 
  border: 1.5px solid var(--border); 
  border-radius: 20px; 
  padding: 30px 28px; 
  transition: all 320ms cubic-bezier(0.16, 1, 0.3, 1); 
