.stat-suffix { font-family: var(--font-heading), sans-serif; font-size: clamp(32px, 3.8vw, 50px); font-weight: 800; color: var(--accent); margin-left: 2px; }
.stat-label { font-size: 19px; font-weight: 700; color: var(--text); margin-top: 16px; margin-bottom: 8px; }
