/* ── 4. Parallax Split Section ── */
.px-grid { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(36px, 5vw, 68px); align-items: center; }
.px-media { position: relative; aspect-ratio: 4/3; border-radius: 22px; overflow: hidden; border: 1.5px solid var(--border); box-shadow: var(--card-shadow); background: rgba(var(--accent-rgb), 0.08); }
.px-media img { width: 100%; height: 100%; object-fit: cover; }
.feature-list { display: flex; flex-direction: column; gap: 18px; margin-top: 12px; }
.feature-item { 
