}
.feature-icon-box svg { width: 20px; height: 20px; }
.feature-item h4 { font-size: 17.5px; margin-bottom: 6px; color: var(--text); font-weight: 700; }
.feature-item p { font-size: 14.5px; color: var(--text-soft); line-height: 1.55; }

/* ── 5. Option Grid Section ── */
.og-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(290px, 1fr)); gap: 26px; }
.og-card { 
  background: var(--surface); 
  border: 1.5px solid var(--border); 
  border-radius: 22px; 
  padding: 34px 30px; 
  transition: transform 260ms var(--ease), border-color 260ms, box-shadow 260ms; 
  box-shadow: var(--card-shadow);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  display: flex; flex-direction: column;
}
.og-card:hover { 
  transform: translateY(-8px); 
  border-color: var(--accent); 
  box-shadow: 0 20px 45px -10px rgba(var(--accent-rgb), 0.3), var(--card-shadow); 
}
.card-tag { 
  align-self: flex-start; display: inline-block; 
  padding: 5px 12px; border-radius: 8px; 
  background: var(--accent-soft); color: var(--accent); 
  font-size: 11.5px; font-weight: 800; text-transform: uppercase; 
  letter-spacing: 0.08em; margin-bottom: 16px; border: 1px solid rgba(var(--accent-rgb), 0.3); 
}
.og-card h3 { font-size: 21px; margin-bottom: 10px; color: var(--text); font-weight: 700; }
.og-card p { font-size: 14.5px; color: var(--text-soft); line-height: 1.6; }

/* ── 6. Timeline Track Section ── */
.timeline-track { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 26px; position: relative; margin-top: 24px; }
.timeline-step { 
  background: var(--surface); 
  border: 1.5px solid var(--border); 
  border-radius: 22px; 
  padding: 32px 28px; 
  position: relative; 
  box-shadow: var(--card-shadow);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  transition: transform 240ms var(--ease), border-color 240ms;
}
.timeline-step:hover { transform: translateY(-6px); border-color: var(--accent); }
.step-indicator { display: flex; align-items: center; gap: 10px; margin-bottom: 16px; }
.step-dot { width: 14px; height: 14px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 14px var(--accent); }
.step-num { font-size: 12px; font-weight: 800; color: var(--accent); text-transform: uppercase; letter-spacing: 0.12em; }
.timeline-step h3 { font-size: 19px; margin-bottom: 8px; color: var(--text); font-weight: 700; }
.timeline-step p { font-size: 14px; color: var(--text-soft); line-height: 1.55; }

/* ── 7. Closing Section ── */
.section-closing { justify-content: center; text-align: center; min-height: 85vh; min-height: 85dvh; }
.closing-card { 
  max-width: 840px; margin: 0 auto; padding: 52px 42px; 
  border-radius: 28px; background: var(--surface); 
  border: 1.5px solid var(--border); 
  box-shadow: 0 24px 60px -12px rgba(var(--accent-rgb), 0.25), var(--card-shadow); 
  backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); 
}
.closing-title { font-size: clamp(36px, 5.5vw, 70px); font-weight: 800; letter-spacing: -0.04em; line-height: 1.1; margin-bottom: 20px; color: var(--text); }
.closing-sub { color: var(--text-soft); max-width: 56ch; margin: 0 auto; font-size: 18px; line-height: 1.65; }
.closing-cta, .hero-cta, .cta-btn, [class*="cta"] { display: none !important; }

/* ── Chart Container ── */
.chart-container { 
  width: 100%; height: 320px; position: relative; margin-top: 20px; 
  background: var(--surface); border: 1.5px solid var(--border); 
  border-radius: 20px; padding: 24px; box-shadow: var(--card-shadow); 
  backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); 
}

/* ── Abstract Visual Fallback (When no photo available) ── */
.abstract-visual { 
  width: 100%; height: 100%; min-height: 280px; 
  display: flex; flex-direction: column; align-items: center; justify-content: center; 
  background: radial-gradient(circle at 30% 30%, rgba(var(--accent-rgb), 0.22), transparent 70%), 
              radial-gradient(circle at 70% 70%, rgba(var(--accent2-rgb), 0.18), transparent 70%), 
              var(--surface); 
  border: 1.5px solid var(--border); border-radius: 22px; 
  box-shadow: var(--card-shadow); position: relative; overflow: hidden; padding: 32px; text-align: center; 
}
.abstract-visual-icon { 
  width: 60px; height: 60px; border-radius: 16px; 
  background: var(--accent-soft); color: var(--accent); 
  display: flex; align-items: center; justify-content: center; 
