/* ── GSAP Reveal States ── */
[data-reveal] { opacity: 0; }
.reveal-arming { will-change: opacity, transform; }
[data-reveal="slide-up"] { transform: translateY(35px); }
[data-reveal="tilt-3d"] { transform: perspective(900px) rotateX(8deg) translateY(25px); }
[data-reveal="fade"] { transform: none; }
[data-reveal="mask-wipe"] { clip-path: inset(0 100% 0 0); transform: none; }

/* ── Edit Toolbar ── */
#scroll-toolbar { position: fixed; bottom: 24px; right: 24px; z-index: 3000; display: flex; gap: 10px; }
