.stool-btn { padding: 10px 22px; border-radius: 12px; border: 1.5px solid var(--border); background: var(--surface); color: var(--text); font-size: 13.5px; font-weight: 700; cursor: pointer; -webkit-backdrop-filter: blur(16px); backdrop-filter: blur(16px); box-shadow: var(--card-shadow); transition: all 180ms; }
