<body>

<div id="scroll-rail"></div>
<div id="section-dots"></div>

${sectionsHtml}

<div id="scroll-toolbar">
  <button id="edit-toggle-btn" class="stool-btn">${lbl.editBtn}</button>
  <button id="save-btn" class="stool-btn" style="display:none;">${lbl.save}</button>
</div>

<script>
(function(){
  gsap.registerPlugin(ScrollTrigger);
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var sections = Array.from(document.querySelectorAll('.scroll-section'));
  var rail     = document.getElementById('scroll-rail');
  var dotsWrap = document.getElementById('section-dots');

  // progress rail
  function updateRail(){
    var doc = document.documentElement;
    var pct = window.scrollY / (doc.scrollHeight - doc.clientHeight) * 100;
    rail.style.width = Math.min(100, Math.max(0, pct)) + '%';
  }
  window.addEventListener('scroll', updateRail, {passive:true});
  updateRail();

  // nav dots
  sections.forEach(function(sec, i){
    var d = document.createElement('div');
    d.className = 'dot';
    d.title = sec.dataset.navLabel || ('Section ' + (i+1));
    d.addEventListener('click', function(){
      sec.scrollIntoView({behavior: rm ? 'auto' : 'smooth'});
    });
    dotsWrap.appendChild(d);
  });
  var dots = Array.from(dotsWrap.children);

  // ===== WCAG 2.2 KEYBOARD NAVIGATION =====
  var currentSecIdx = 0;
  function updateCurrentSec() {
    var mid = window.scrollY + window.innerHeight / 2;
    for (var i = 0; i < sections.length; i++) {
      var top = sections[i].offsetTop;
      var h = sections[i].offsetHeight;
      if (mid >= top && mid < top + h) { currentSecIdx = i; break; }
    }
  }
  window.addEventListener('scroll', updateCurrentSec, { passive: true });

  window.addEventListener('keydown', function(e) {
    if (e.target && (e.target.isContentEditable || ['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))) return;
    if (e.key === 'ArrowDown' || e.key === 'PageDown' || e.key === ' ') {
      if (currentSecIdx < sections.length - 1) {
        e.preventDefault();
        sections[currentSecIdx + 1].scrollIntoView({ behavior: rm ? 'auto' : 'smooth' });
      }
    } else if (e.key === 'ArrowUp' || e.key === 'PageUp') {
      if (currentSecIdx > 0) {
        e.preventDefault();
        sections[currentSecIdx - 1].scrollIntoView({ behavior: rm ? 'auto' : 'smooth' });
      }
    } else if (e.key === 'Home') {
      e.preventDefault();
      sections[0].scrollIntoView({ behavior: rm ? 'auto' : 'smooth' });
    } else if (e.key === 'End') {
      e.preventDefault();
      sections[sections.length - 1].scrollIntoView({ behavior: rm ? 'auto' : 'smooth' });
    }
  });

  if (!rm) {
    sections.forEach(function(sec, i){
      ScrollTrigger.create({
        trigger: sec, start: 'top center', end: 'bottom center',
        onToggle: function(self){ if(self.isActive) dots.forEach(function(d,j){ d.classList.toggle('active', j===i); }); }
      });
    });
  } else { if(dots[0]) dots[0].classList.add('active'); }

  // 1. HERO IMMEDIATE REVEAL (Never starts blank or delayed on page load!)
  if (!rm) {
    gsap.to('.section-hero [data-reveal]', {
      opacity: 1, y: 0, rotationX: 0, duration: 0.85, stagger: 0.12, ease: 'power3.out',
      onStart: function(){ document.querySelectorAll('.section-hero [data-reveal]').forEach(function(el){ el.classList.add('reveal-arming'); }); },
      onComplete: function(){ document.querySelectorAll('.section-hero [data-reveal]').forEach(function(el){ el.classList.remove('reveal-arming'); }); }
    });
  } else {
    document.querySelectorAll('.section-hero [data-reveal]').forEach(function(el){ el.style.opacity=1; el.style.transform='none'; });
  }

  // 2. SUBSEQUENT SECTIONS REVEAL WITH SCROLLTRIGGER
  if (!rm) {
    document.querySelectorAll('.scroll-section:not(.section-hero) [data-reveal]').forEach(function(el){
      var type = el.dataset.reveal || 'slide-up';
      var vars = {opacity:1, duration:0.75, ease:'power3.out',
        onStart: function(){ el.classList.add('reveal-arming'); },
        onComplete: function(){ el.classList.remove('reveal-arming'); }
      };
      if (type === 'slide-up') vars.y = 0;
      if (type === 'tilt-3d') { vars.y = 0; vars.rotationX = 0; vars.transformPerspective = 900; }
      if (type === 'mask-wipe') vars.clipPath = 'inset(0 0% 0 0)';
      gsap.to(el, Object.assign(vars, {
        scrollTrigger: { trigger: el, start: 'top 85%', toggleActions: 'play none none reverse' }
      }));
    });
  } else {
    document.querySelectorAll('.scroll-section:not(.section-hero) [data-reveal]').forEach(function(el){ el.style.opacity=1; el.style.transform='none'; });
  }

  // 3. STICKY-MEDIA ACTIVE CARD HIGHLIGHT
  document.querySelectorAll('.section-sticky-media').forEach(function(sec){
    var cards = sec.querySelectorAll('[data-sm-line]');
    if (!cards.length) return;
    if (rm) { cards.forEach(function(c){ c.classList.add('is-active'); }); return; }
    cards.forEach(function(card){
      ScrollTrigger.create({
        trigger: card, start: 'top 60%', end: 'bottom 40%',
        onEnter: function(){ card.classList.add('is-active'); },
        onLeaveBack: function(){ card.classList.remove('is-active'); }
      });
    });
  });

  // 4. STAT COUNT-UP (FIXED: respects decimal points like 3.5x, 99.9%)
  document.querySelectorAll('[data-count-to]').forEach(function(el){
    var target = parseFloat(el.dataset.countTo);
    var rawStr = String(el.dataset.countTo || '');
    var decimals = rawStr.includes('.') ? (rawStr.split('.')[1].length) : 0;
    var suffix = el.dataset.suffix || '';
    if (isNaN(target)) return;
    var obj = {v:0};
    if (rm) { el.textContent = target.toFixed(decimals) + suffix; return; }
    ScrollTrigger.create({
      trigger: el, start: 'top 85%', once: true,
      onEnter: function(){
        gsap.to(obj, {v:target, duration:1.8, ease:'power2.out',
          onUpdate: function(){ el.textContent = obj.v.toFixed(decimals) + suffix; }
        });
      }
    });
  });

  // 5. PARALLAX FOREGROUND
  if (!rm) {
    document.querySelectorAll('[data-parallax-fg]').forEach(function(el){
      gsap.fromTo(el, {yPercent:-5}, {yPercent:5, ease:'none', force3D:true,
        scrollTrigger:{trigger:el.closest('.scroll-section'), start:'top bottom', end:'bottom top', scrub:0.4}
      });
    });
  }

  // 6. AUTO-INIT CHART.JS (When data-chart-config is present)
  document.querySelectorAll('.chart-canvas[data-chart-config]').forEach(function(canvas){
    try {
      var cfg = JSON.parse(canvas.dataset.chartConfig);
      var accentColor = getComputedStyle(document.documentElement).getPropertyValue('--accent') || '#2563EB';
      new Chart(canvas, {
        type: cfg.type || 'bar',
        data: {
          labels: cfg.labels || [],
          datasets: [{
            label: cfg.title || '',
            data: (cfg.series && cfg.series[0] && cfg.series[0].data) ? cfg.series[0].data : (cfg.series || []),
            backgroundColor: accentColor,
            borderRadius: 8
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { display: !!cfg.title } }
        }
      });
    } catch(e) { console.warn('Chart init error:', e); }
  });

  // 7. EDIT IN PLACE
  var editToggleBtn = document.getElementById('edit-toggle-btn');
  var saveBtn       = document.getElementById('save-btn');
  var isEditMode    = false;

  function toggleEditMode(){
    isEditMode = !isEditMode;
    document.querySelectorAll('.editable-text').forEach(function(el){
      el.contentEditable = isEditMode ? 'true' : 'false';
    });
    document.body.classList.toggle('editing-active', isEditMode);
    editToggleBtn.textContent = isEditMode ? '${lbl.doneBtn}' : '${lbl.editBtn}';
    saveBtn.style.display = isEditMode ? 'block' : 'none';
  }

  async function saveChanges(){
    saveBtn.textContent = '${lbl.saving}';
    saveBtn.disabled = true;
    var n8nUrl = window.__N8N_UPDATE_URL__;
    var token  = window.__PRESENTATION_TOKEN__;
    if (!n8nUrl) { saveBtn.textContent = 'Config error'; saveBtn.disabled = false; return; }
    try {
      var bodyHtml = document.body.innerHTML;
      var hdr = {'Content-Type':'application/json'};
      if (token) hdr['x-presentation-token'] = token;
      var resp = await fetch(n8nUrl, {
        method: 'POST', headers: hdr,
        body: JSON.stringify({ slug: window.location.hostname.split('.')[0], htmlContent: bodyHtml })
      });
      if (resp.ok) {
        saveBtn.textContent = '${lbl.saved}';
        setTimeout(function(){ location.reload(); }, 1200);
      } else { throw new Error('fail'); }
    } catch(e) {
      saveBtn.textContent = 'Gagal, coba lagi';
      saveBtn.disabled = false;
    }
  }

  editToggleBtn.addEventListener('click', toggleEditMode);
  saveBtn.addEventListener('click', saveChanges);
  ScrollTrigger.refresh();
})();
</script>

