function cleanStr(str, maxLen) {
    if (!str || typeof str !== "string") return "";
    return str
        .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "")
        .replace(/ignore\s+(all\s+)?(previous|above|prior)\s+instructions?/gi, "[DIHAPUS]")
        .replace(/you\s+are\s+now\s+(a\s+)?/gi, "[DIHAPUS] ")
        .replace(/forget\s+(everything|all)\s+(you|above)/gi, "[DIHAPUS]")
        .replace(/system\s*:\s*/gi, "[DIHAPUS]: ")
        .replace(/\[INST\]|\[\/INST\]|<\|system\|>|<\|user\|>|<\|assistant\|>/gi, "[DIHAPUS]")
        .replace(/\{\{/g, "{ {")
        .replace(/\}\}/g, "} }")
        .slice(0, maxLen)
        .trim();
}

const technicalPatterns = [
    /webhookId/i, /x-real-ip/i, /user-agent/i, /"headers"\s*:/i,
    /authorization:\s*bearer/i, /api[_-]?key\s*[:=]/i, /access[_-]?token\s*[:=]/i,
    /"typeVersion"/i, /"nodeGroups"/i, /-----BEGIN .* KEY-----/i
];

// Check approvedOutline directly on item or formatted input
const approvedOutlinePresent = !!(
    (item.approvedOutline && Array.isArray(item.approvedOutline.sections) && item.approvedOutline.sections.length > 0) ||
    (item.approvedOutline && Array.isArray(item.approvedOutline.slides) && item.approvedOutline.slides.length > 0)
);

const rawInputMaterial = item.material || item.rawText || (approvedOutlinePresent && Array.isArray(item.approvedOutline.sections) 
    ? item.approvedOutline.sections.map(s => (s.title || '') + ' ' + (s.narrative || '')).join(' ') 
    : "");

for (const pattern of technicalPatterns) {
    if (pattern.test(rawInputMaterial)) {
        throw new Error("REJECTED: Materi terdeteksi sebagai data teknis/sistem, bukan konten presentasi.");
    }
}

let sanitizedMaterial = cleanStr(rawInputMaterial, 25000);

if (sanitizedMaterial.length < 15) {
    throw new Error("REJECTED: Materi terlalu pendek untuk diproses.");
}

// Sanitize approvedOutline sections if present
let sanitizedApprovedOutline = item.approvedOutline;
if (sanitizedApprovedOutline && typeof sanitizedApprovedOutline === 'object') {
